(function(){'use strict';
const api=window.AvalonOverlay,$=id=>document.getElementById(id);let portal=null;
function timer(){const e=$('portal-timer');e.hidden=!portal;if(!portal)return;const seconds=portal.expires===null?null:Math.max(0,Math.floor((portal.expires-Date.now())/1000));e.textContent='Из '+portal.from+' · '+(seconds===null?'таймер не прочитан':seconds===0?'время истекло':'до закрытия '+Math.floor(seconds/3600)+' ч '+Math.floor(seconds%3600/60)+' мин '+seconds%60+' с');}
setInterval(timer,1000);
function paint({zone:z,portal:p}){if(!z)return;portal=p||null;timer();$('zone-kind').textContent=portal?'СЧИТАННЫЙ ПОРТАЛ':'КАРТА ЗОНЫ';$('zone-name').textContent=z.name;$('zone-meta').textContent='T'+AvalonMath.zoneLabel(z)+' · '+(AvalonMath.worlds[z.world]||z.world);document.body.classList.toggle('no-map',!z.image);if(z.image){const img=new Image();img.alt='Карта '+z.name;img.src='avalon-local/'+encodeURIComponent(z.image);$('map').replaceChildren(img);}else{const note=document.createElement('p');note.className='map-empty';note.textContent='Карта зоны отсутствует в справочнике.';$('map').replaceChildren(note);}const groups=AvalonMath.featureGroups(z).filter(group=>group.items.length),fragment=document.createDocumentFragment();for(const group of groups){const section=document.createElement('section'),title=document.createElement('h2'),items=document.createElement('p');title.textContent=group.title;items.textContent=group.items.join(' · ');section.append(title,items);fragment.append(section);}if(!groups.length){const note=document.createElement('p');note.className='hint';note.textContent='Объекты в справочнике не указаны.';fragment.append(note);}$('features').replaceChildren(fragment);}
api.onZone(paint);api.state().then(paint);$('close').onclick=()=>api.control('close');$('pin').onclick=async()=>{const state=await api.control('pin');$('pin').setAttribute('aria-pressed',String(state.pinned));};
})();
